// Declares the app's own commands to Tauri, so each window's capability can list the ones it may call (and the
// others are refused: src-tauri/capabilities, generated by scripts/tauri-capabilities.mjs; docs/security.md, ZE-14).
// The list is read from `collect_commands![…]` in src/lib.rs, so a new command needs no second place to be added.

fn main() {
    println!("cargo:rerun-if-changed=src/lib.rs");
    let lib = std::fs::read_to_string("src/lib.rs").expect("src/lib.rs");
    let block = lib
        .split("collect_commands![")
        .nth(1)
        .and_then(|rest| rest.split("])").next())
        .expect("collect_commands![ … ] in src/lib.rs");
    let names: Vec<&'static str> = block
        .split(',')
        .filter_map(|item| item.trim().rsplit("::").next())
        .filter(|name| !name.is_empty() && name.chars().all(|c| c.is_ascii_alphanumeric() || c == '_'))
        .map(|name| &*Box::leak(name.to_string().into_boxed_str()))
        .collect();
    let commands: &'static [&'static str] = Box::leak(names.into_boxed_slice());
    tauri_build::try_build(tauri_build::Attributes::new().app_manifest(tauri_build::AppManifest::new().commands(commands)))
        .expect("tauri build");
}
